from collections import defaultdict

class Solution:
    def fixedRatio(self, s: str, num1: int, num2: int) -> int:
        counts = defaultdict(int)
        counts[0] = 1
        cur = 0
        ans = 0
        for c in s:
            if c == '0':
                cur += num2
            else:
                cur -= num1
            ans += counts[cur]
            counts[cur] += 1
        return ans

class Solution {
public:
    long long fixedRatio(std::string s, int num1, int num2) {
        std::unordered_map<long long, int> counts;
        counts[0] = 1;
        long long cur = 0;
        long long ans = 0;
        for (char c : s) {
            if (c == '0') cur += num2;
            else cur -= num1;
            ans += counts[cur];
            counts[cur]++;
        }
        return ans;
    }
};

class Solution {
    public long fixedRatio(String s, int num1, int num2) {
        java.util.Map<Long, Integer> counts = new java.util.HashMap<>();
        counts.put(0L, 1);
        long cur = 0;
        long ans = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '0') cur += num2;
            else cur -= num1;
            ans += counts.getOrDefault(cur, 0);
            counts.put(cur, counts.getOrDefault(cur, 0) + 1);
        }
        return ans;
    }
}

